reset role;
select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(jsonb_array_length(public.study_room_schedule(pg_temp.tomorrow())->'resources')=12,'authorized member sees 12 resources');
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->>'canManage'='false','ordinary user has no app administration');
select pg_temp.denied('select * from app_private.study_bookings','42501','private booking table denied');
select pg_temp.denied('select * from app_private.study_request_receipts','42501','private receipts denied');
select pg_temp.denied('select * from app_private.study_slots','42501','direct slot reads denied');
select pg_temp.denied('select app_private.study_is_manager(''44444444-4444-4444-8444-000000000101'')','42501','no arbitrary actor authority oracle');
select public.study_room_command(pg_temp.command('95000000-0000-4000-8000-000000000001',1,780,840));
select pg_temp.pass(jsonb_array_length(public.study_room_schedule(pg_temp.tomorrow())->'bookings')=1,'reservation appears on schedule');
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'detail'='Private Example Contact','owner sees own private detail');
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'mine'='true','owner status derived server-side');
select pg_temp.pass(public.member_module_home()->'activities'->0->>'title'='Study Room Reservation · Room 1','booking generates safe My Week title');
select pg_temp.pass(not(public.member_module_home()::text like '%Private Example Contact%'),'private detail absent from activities and notices');
select public.study_room_command(pg_temp.command('95000000-0000-4000-8000-000000000001',1,780,840));
select pg_temp.pass(jsonb_array_length(public.study_room_schedule(pg_temp.tomorrow())->'bookings')=1,'exact request retry is idempotent');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command('95000000-0000-4000-8000-000000000001',1,840,870))$q$,'22023','idempotency key cannot be repurposed');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),1,810,870))$q$,'23505','partially overlapping request denied');
select public.study_room_command(pg_temp.command('95000000-0000-4000-8000-000000000002',1,840,870));
select pg_temp.pass(jsonb_array_length(public.study_room_schedule(pg_temp.tomorrow())->'bookings')=2,'back-to-back reservation allowed');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),2,780,840)||'{"memberId":"44444444-4444-4444-8444-000000000103"}')$q$,'22023','forged owner rejected by database');
select pg_temp.denied($q$select public.study_room_command((pg_temp.command(gen_random_uuid(),2,780,840)-'purpose'-'detail')||'{"action":"hold","reason":"Unauthorized hold"}')$q$,'42501','ordinary member cannot place hold');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),2,785,845))$q$,'22023','off-grid times rejected');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),2,780,840)||'{"detail":{"bad":true}}')$q$,'22023','database rejects non-text detail');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),2,780,840)||jsonb_build_object('day',(pg_temp.tomorrow()+4)::text))$q$,'22023','outside booking window rejected');
reset role;
select pg_temp.login(103);set local role authenticated;
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'label'='Reserved','other-group owner name redacted');
select pg_temp.pass(not(public.study_room_schedule(pg_temp.tomorrow())::text like '%Private Example Contact%'),'other-group private purpose detail redacted');
select pg_temp.pass(not(public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0 ? 'purpose'),'other-group purpose category withheld');
select pg_temp.denied($q$select public.study_room_command(jsonb_build_object('requestId',gen_random_uuid(),'action','cancel','expectedVersion',1,'bookingId',public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'id','reason','Unauthorized cancellation'))$q$,'42501','cannot cancel another member booking');
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=0,'another member cannot see My Week activity');
reset role;
select pg_temp.login(101);set local role authenticated;
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->>'canManage'='true','explicit module manager recognized');
select pg_temp.pass(public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'detail'='Private Example Contact','explicit reservation manager may read purpose detail');
select public.study_room_command((pg_temp.command('95000000-0000-4000-8000-000000000003',2,960,1020)-'purpose'-'detail')||'{"action":"hold","reason":"Fictional maintenance"}');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')x where x->>'hold'='true'),'manager hold recorded');
reset role;
select pg_temp.login(107);set local role authenticated;
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),2,960,990))$q$,'23505','manager hold prevents overlap');
select public.study_room_command(jsonb_build_object('requestId','95000000-0000-4000-8000-000000000004','action','cancel','expectedVersion',1,'bookingId',public.study_room_schedule(pg_temp.tomorrow())->'bookings'->0->>'id','reason','Fictional plans changed'));
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')x where x->>'state'='cancelled'),'cancellation retains historical record');
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=1,'cancelled reservation removed from My Week');
select public.study_room_command(pg_temp.command('95000000-0000-4000-8000-000000000005',1,780,840));
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=2,'cancelled time becomes reservable');
