select pg_temp.login(107);update app_private.account_links set technical_enabled=false where member_id='44444444-4444-4444-8444-000000000107';set local role authenticated;
select pg_temp.denied('select public.study_room_schedule(pg_temp.tomorrow())','42501','technical suspension immediately denies availability');
reset role;set local role anon;
select pg_temp.denied('select public.study_room_schedule(pg_temp.tomorrow())','42501','anonymous schedule denied');
select pg_temp.denied($q$select public.study_room_command('{}')$q$,'42501','anonymous booking denied');
reset role;
select pg_temp.pass((select count(*)=6 from pg_tables where schemaname='app_private' and tablename in ('study_resources','study_service_blocks','study_bookings','study_slots','study_request_receipts','study_audit') and rowsecurity),'all six new tables RLS-protected');
rollback;
